return ['domain'=>'zinn-connector','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-connector','pot-creation-date'=>'2026-09-02T07:33:53+00:00','po-revision-date'=>'2026-09-02T07:33:53+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Connector'=>'Zinn® Connector','https://zinndigital.com/wordpress-plugins/zinn-connector'=>'https://zinndigital.com/wordpress-plugins/zinn-connector','Connects this WordPress site to Zinn Digital® so scheduled articles can be published to it. Paste a pairing code from your Zinn® dashboard and the plugin sets up its own credential — nothing is copied by hand.'=>'Povezuje ovu WordPress stranicu sa Zinn Digital® kako bi se na nju mogle objavljivati zakazane objave. Zalijepite kod za uparivanje s vaše Zinn® nadzorne ploče i dodatak sam postavlja svoje vjerodajnice — ništa se ne kopira ručno.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','This site\'s PHP cannot create archives, so a backup could not be made.'=>'PHP ove stranice ne može stสร้างiti arhive, pa sigurnosna kopija nije mogla biti izrađena.','Could not create a temporary file.'=>'Nije moguće stvoriti privremenu datoteku.','This site\'s files could not be archived.'=>'Datoteke ove web-lokacije nije bilo moguće arhivirati.','The archive could not be read back.'=>'Arhiv se nije mogao pročitati.','The backup could not be uploaded.'=>'Sigurnosna kopija se nije mogla učitati.','The backup upload was rejected.'=>'Prijenos sigurnosne kopije je odbijen.','This WordPress user cannot publish posts, so a connection made now could not publish either. Sign in as a user who can, and try again.'=>'Ovaj WordPress korisnik ne može objavljivati postove, tako da se ni veza ostvarena sada ne bi mogla objaviti. Prijavite se kao korisnik koji to može i pokušajte ponovno.','Application passwords are turned off on this site, so we cannot create a credential. Ask your host to enable them, or connect the site with a password you create yourself in your Zinn Digital® dashboard.'=>'Lozinke za aplikacije su isključene na ovoj stranici, stoga ne možemo izraditi vjerodajnicu. Zatražite od svog pružatelja usluge da ih omogući ili povežite stranicu pomoću lozinke koju sami kreirate na svojoj upravljačkoj ploči Zinn Digital®.','WordPress would not create a credential for this site. Nothing has been sent anywhere.'=>'WordPress nije mogao izraditi vjerodajnicu za ovo web-mjesto. Ništa nije poslano nigdje.','We could not reach Zinn Digital® from this site. Nothing was connected, and the credential we made has been removed. Check the site can make outgoing requests, and try again.'=>'Nismo mogli uspostaviti vezu s platformom Zinn Digital® s ove stranice. Ništa nije bilo povezano, a izrađeni vjerodajnički podaci su uklonjeni. Provjerite može li stranica slati odlazne zahtjeve i pokušajte ponovno.','Zinn Digital® did not accept that pairing code. Nothing was connected. Generate a fresh code in your dashboard and try again.'=>'Zinn Digital® nije prihvatio taj kôd za uparivanje. Ništa nije povezano. Generirajte novi kôd na svojoj upravljačkoj ploči i pokušajte ponovno.','Connected. Zinn Digital® can now publish to this site.'=>'Povezano. Zinn Digital® sada može objavljivati na ovoj stranici.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena osobama koje upravljaju s više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite postojeće internetske stranice, domene i postavljanja poveznica, uz sigurno čuvanje novca sve dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite ljude koji se time bave za život','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih zanimanja: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i dopustite im da daju ponude.','This site is connected to Zinn Digital®, publishing as %s.'=>'Ova je stranica povezana sa Zinn Digital®, a objavljuje pod nazivom %s.','To disconnect, revoke the “Zinn Digital® (publishing)” application password on %s.'=>'Za prekid veze, opozovite zaporku aplikacije „Zinn Digital® (publishing)” na %s.','your profile'=>'vaš profil','Connect this site'=>'Povežite ovu web-lokaciju','Open your Zinn Digital® dashboard, go to Content → Other sites, and press “Get a pairing code”. Paste it below.'=>'Otvorite svoju nadzornu ploču Zinn Digital®, idite na Sadržaj → Ostale web-lokacije i pritisnite „Zatražite kod za uparivanje”. Zalijepite ga u nastavku.','Pairing code'=>'Kod za uparivanje','It expires thirty minutes after you generate it, and can only be used once.'=>'Istječe trideset minuta nakon što ga generirate i može se iskoristiti samo jednom.','You are not allowed to connect this site.'=>'Nije vam dopušteno povezivanje ove stranice.']];